def E(name, brief, params=None, returns=None, note=None, see=None, warning=None, **kw):
    d = {"name": name, "brief": brief}
    if params: d["params"] = params
    if returns: d["returns"] = returns
    if note: d["note"] = note
    if warning: d["warning"] = warning
    if see: d["see"] = see
    d.update(kw)
    return d

TF = "TRUE or FALSE"
NIL = "nothing; the hash list changes"
DEAD = "known defect: the call raises error %s today, %s"
HL = "a hash list, as [ [ key, value ], ... ]"


def dead(name, intent, why, params=None, see=None):
    return E(name, "Raises an error today instead of %s." % intent, params=params, returns="nothing today",
             warning=[why], see=see)


